"""
Day 10: Lord Shri Ram Sketch & Happy Diwali Devotional Art
30 Days Python Challenge by Tejas (@Tejas0113)

Description:
An enhanced, high-precision devotional vector line sketch of Lord Shri Ram with
the Kodanda Bow, Tarkash Quiver of arrows, and sacred tilak.
Rendered stroke-by-stroke with dual-layer saffron-gold neon radiance using Python Turtle graphics,
accompanied by traditional glowing terracotta diyas and an auspicious Happy Diwali blessing.
"""

import base64
import json
import turtle as t
import zlib

# High-precision vector stroke paths (anatomically grouped and RDP-smoothed)
_RAM_SKETCH_DATA = ""


def get_sketch_paths():
    """Decompresses and returns the vector stroke polylines."""
    raw = zlib.decompress(base64.b64decode(_RAM_SKETCH_DATA))
    return json.loads(raw.decode("utf-8"))


def draw_diya(t_pen, x, y, scale=1.0):
    """Draws an ornamental glowing terracotta Diwali diya at (x, y)."""
    t_pen.penup()

    # 1. Warm radial ambient glow beneath diya
    t_pen.goto(x, y - 4 * scale)
    t_pen.dot(int(36 * scale), "#381806")
    t_pen.goto(x, y + 8 * scale)
    t_pen.dot(int(26 * scale), "#662808")

    # 2. Terracotta clay bowl
    t_pen.goto(x - 24 * scale, y)
    t_pen.pendown()
    t_pen.pencolor("#B85414")
    t_pen.fillcolor("#9E4410")
    t_pen.pensize(2)
    t_pen.begin_fill()
    t_pen.goto(x - 16 * scale, y - 11 * scale)
    t_pen.goto(x + 16 * scale, y - 11 * scale)
    t_pen.goto(x + 24 * scale, y)
    t_pen.goto(x, y - 2 * scale)
    t_pen.goto(x - 24 * scale, y)
    t_pen.end_fill()
    t_pen.penup()

    # 3. Golden metallic rim
    t_pen.goto(x - 24 * scale, y)
    t_pen.pendown()
    t_pen.pencolor("#FFD700")
    t_pen.pensize(2)
    t_pen.goto(x + 24 * scale, y)
    t_pen.penup()

    # 4. Outer radiant orange flame
    t_pen.goto(x, y + 2 * scale)
    t_pen.pendown()
    t_pen.pencolor("#FF6600")
    t_pen.fillcolor("#FF8C00")
    t_pen.begin_fill()
    t_pen.goto(x - 8 * scale, y + 10 * scale)
    t_pen.goto(x, y + 26 * scale)
    t_pen.goto(x + 8 * scale, y + 10 * scale)
    t_pen.goto(x, y + 2 * scale)
    t_pen.end_fill()
    t_pen.penup()

    # 5. Inner luminous golden core
    t_pen.goto(x, y + 4 * scale)
    t_pen.pendown()
    t_pen.pencolor("#FFE88A")
    t_pen.fillcolor("#FFF9D2")
    t_pen.begin_fill()
    t_pen.goto(x - 4 * scale, y + 10 * scale)
    t_pen.goto(x, y + 18 * scale)
    t_pen.goto(x + 4 * scale, y + 10 * scale)
    t_pen.goto(x, y + 4 * scale)
    t_pen.end_fill()
    t_pen.penup()


def draw_ram_diwali():
    """Renders Lord Shri Ram in glowing saffron strokes and writes the Diwali wish."""
    screen = t.Screen()
    screen.setup(width=880, height=960)
    screen.title("Day 10: Lord Shri Ram Sketch & Happy Diwali Devotional Art")
    screen.bgcolor("#05070E")
    t.setworldcoordinates(-440, -490, 440, 470)

    # Smooth animated drawing buffer
    t.tracer(4, 5)
    t.hideturtle()
    t.speed(0)

    paths = get_sketch_paths()

    scale = 1.42
    x_center = 250
    y_center = 328
    y_offset = 85

    # Pass 1: Warm ambient amber undertone (creates neon glow)
    t.pensize(3)
    t.pencolor("#B85412")

    for path in paths:
        t.penup()
        p0 = path[0]
        t.goto((p0[0] - x_center) * scale, (y_center - p0[1]) * scale + y_offset)
        t.pendown()
        for pt in path[1:]:
            t.goto((pt[0] - x_center) * scale, (y_center - pt[1]) * scale + y_offset)

    # Pass 2: High-luminance radiant saffron-gold core
    t.pensize(2)
    t.pencolor("#FFA228")

    for path in paths:
        t.penup()
        p0 = path[0]
        t.goto((p0[0] - x_center) * scale, (y_center - p0[1]) * scale + y_offset)
        t.pendown()
        for pt in path[1:]:
            t.goto((pt[0] - x_center) * scale, (y_center - pt[1]) * scale + y_offset)

    t.penup()

    # Traditional glowing Diyas flanking the bottom greeting
    draw_diya(t, -225, -330, scale=1.15)
    draw_diya(t, 225, -330, scale=1.15)

    # Sacred Devanagari Title
    t.goto(0, -260)
    t.pencolor("#FFD700")
    t.write("|| जय श्री राम ||", align="center", font=("Devanagari MT", 26, "bold"))

    # Golden Divider Rule
    t.pensize(2)
    t.pencolor("#D29623")
    t.goto(-170, -282)
    t.pendown()
    t.goto(170, -282)
    t.penup()

    # Happy Diwali Greeting
    t.goto(0, -335)
    t.pencolor("#FFA828")
    t.write("HAPPY DIWALI", align="center", font=("Arial", 34, "bold"))

    # Festive Blessings
    t.goto(0, -388)
    t.pencolor("#FFF2D1")
    t.write(
        "May the Divine Grace of Lord Shri Ram Illuminate Your Life",
        align="center",
        font=("Georgia", 14, "normal")
    )

    t.goto(0, -416)
    t.pencolor("#E0BE82")
    t.write(
        "With Peace, Health, Happiness & Infinite Prosperity",
        align="center",
        font=("Georgia", 14, "normal")
    )

    t.update()


def main():
    try:
        draw_ram_diwali()
        t.done()
    except (t.Terminator, KeyboardInterrupt, Exception):
        pass


if __name__ == "__main__":
    main()
